def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(c - r, v) for r, row in enumerate(grid)
              for c, v in enumerate(row) if v != 0]

    # The colored marks lie on diagonals. Find the smallest repeating
    # diagonal period consistent with all the marks.
    period = 1
    while True:
        mapping = {}
        valid = True
        for offset, color in points:
            residue = offset % period
            if residue in mapping and mapping[residue] != color:
                valid = False
                break
            mapping[residue] = color
        if valid:
            break
        period += 1

    # Fill any unobserved residue by extending the known residue cycle.
    if len(mapping) < period:
        known = sorted(mapping)
        for residue in range(period):
            if residue not in mapping:
                nearest = min(known, key=lambda x: min((residue-x) % period, (x-residue) % period))
                mapping[residue] = mapping[nearest]

    return [[mapping[(c-r) % period] for c in range(w)] for r in range(h)]
